-- The cases of test_run_sql_correlated: each COPY line below is one case, the
-- query DuckDB runs over the tables of data.sql and the file its answer goes
-- to. The test reads THIS FILE for the query text and runs the same text
-- through run_sql over the same Parquet files, each registered under its table
-- name, so a query has one source. A case's name is its output file without
-- `.tsv`. The tpch_* lines are the corpus texts of src/bench_corpus with their
-- white space collapsed to one space, which the test checks. Derived from
-- TPC-H; not comparable to published TPC-H results.
CREATE VIEW region AS SELECT * FROM read_parquet('region.parquet');
CREATE VIEW nation AS SELECT * FROM read_parquet('nation.parquet');
CREATE VIEW supplier AS SELECT * FROM read_parquet('supplier.parquet');
CREATE VIEW part AS SELECT * FROM read_parquet('part.parquet');
CREATE VIEW partsupp AS SELECT * FROM read_parquet('partsupp.parquet');
CREATE VIEW customer AS SELECT * FROM read_parquet('customer.parquet');
CREATE VIEW orders AS SELECT * FROM read_parquet('orders.parquet');
CREATE VIEW lineitem AS SELECT * FROM read_parquet('lineitem.parquet');
COPY (select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 15 and p_type like '%BRASS' and s_nationkey = n_nationkey and n_regionkey = r_regionkey and r_name = 'EUROPE' and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and r_name = 'EUROPE' ) order by s_acctbal desc, n_name, s_name, p_partkey limit 100) TO 'tpch_q2.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select s_acctbal, s_name, n_name, p_partkey, p_mfgr, s_address, s_phone, s_comment from part, supplier, partsupp, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and p_size = 15 and p_type like '%BRASS' and s_nationkey = n_nationkey and n_regionkey = r_regionkey and r_name = 'EUROPE' and ps_supplycost = ( select min(ps_supplycost) from partsupp, supplier, nation, region where p_partkey = ps_partkey and s_suppkey = ps_suppkey and s_nationkey = n_nationkey and n_regionkey = r_regionkey and r_name = 'EUROPE' )) TO 'tpch_q2_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select o_orderpriority, count(*) as order_count from orders where o_orderdate >= date '1993-07-01' and o_orderdate < date '1993-07-01' + interval '3' month and exists ( select * from lineitem where l_orderkey = o_orderkey and l_commitdate < l_receiptdate ) group by o_orderpriority order by o_orderpriority) TO 'tpch_q4.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select sum(l_extendedprice) / 7.0 as avg_yearly from lineitem, part where p_partkey = l_partkey and p_brand = 'Brand#23' and p_container = 'MED BOX' and l_quantity < ( select 0.2 * avg(l_quantity) from lineitem where l_partkey = p_partkey )) TO 'tpch_q17.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select s_name, s_address from supplier, nation where s_suppkey in ( select ps_suppkey from partsupp where ps_partkey in ( select p_partkey from part where p_name like 'forest%' ) and ps_availqty > ( select 0.5 * sum(l_quantity) from lineitem where l_partkey = ps_partkey and l_suppkey = ps_suppkey and l_shipdate >= date '1994-01-01' and l_shipdate < date '1994-01-01' + interval '1' year ) ) and s_nationkey = n_nationkey and n_name = 'CANADA' order by s_name) TO 'tpch_q20.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select s_name, count(*) as numwait from supplier, lineitem l1, orders, nation where s_suppkey = l1.l_suppkey and o_orderkey = l1.l_orderkey and o_orderstatus = 'F' and l1.l_receiptdate > l1.l_commitdate and exists ( select * from lineitem l2 where l2.l_orderkey = l1.l_orderkey and l2.l_suppkey <> l1.l_suppkey ) and not exists ( select * from lineitem l3 where l3.l_orderkey = l1.l_orderkey and l3.l_suppkey <> l1.l_suppkey and l3.l_receiptdate > l3.l_commitdate ) and s_nationkey = n_nationkey and n_name = 'SAUDI ARABIA' group by s_name order by numwait desc, s_name limit 100) TO 'tpch_q21.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (select cntrycode, count(*) as numcust, sum(c_acctbal) as totacctbal from ( select substring(c_phone from 1 for 2) as cntrycode, c_acctbal from customer where substring(c_phone from 1 for 2) in ('13', '31', '23', '29', '30', '18', '17') and c_acctbal > ( select avg(c_acctbal) from customer where c_acctbal > 0.00 and substring(c_phone from 1 for 2) in ('13', '31', '23', '29', '30', '18', '17') ) and not exists ( select * from orders where o_custkey = c_custkey ) ) as custsale group by cntrycode order by cntrycode) TO 'tpch_q22.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE (SELECT count(*) FROM lineitem WHERE l_partkey = p_partkey) = 0) TO 'scalar_count_no_match.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE (SELECT count(*) FROM lineitem WHERE l_partkey = p_partkey) < 4) TO 'scalar_count_compare.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE p_retailprice * 25 > (SELECT avg(l_extendedprice) FROM lineitem WHERE l_partkey = p_partkey)) TO 'scalar_avg_no_match.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT ps_partkey, ps_suppkey FROM partsupp WHERE ps_availqty > (SELECT 0.1 * sum(l_quantity) FROM lineitem WHERE l_partkey = ps_partkey AND l_suppkey = ps_suppkey)) TO 'scalar_two_keys.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT ps_partkey, ps_suppkey FROM partsupp WHERE (SELECT min(l_quantity) FROM lineitem WHERE l_partkey = ps_partkey) >= ps_availqty) TO 'scalar_left_operand.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey, (SELECT max(l_quantity) FROM lineitem WHERE l_partkey = p_partkey) AS mq FROM part) TO 'scalar_select_item.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o_orderkey FROM orders WHERE EXISTS (SELECT * FROM customer WHERE c_custkey = o_custkey)) TO 'exists_null_outer_key.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o_orderkey FROM orders WHERE NOT EXISTS (SELECT * FROM customer WHERE c_custkey = o_custkey)) TO 'not_exists_null_outer_key.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT s_suppkey FROM supplier WHERE NOT EXISTS (SELECT * FROM lineitem WHERE l_suppkey = s_suppkey AND l_quantity > 48)) TO 'not_exists_null_inner_key.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT c_custkey FROM customer WHERE EXISTS (SELECT * FROM orders, lineitem WHERE o_orderkey = l_orderkey AND o_custkey = c_custkey AND l_quantity > 45)) TO 'exists_join_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT c_custkey FROM customer WHERE EXISTS (SELECT * FROM orders WHERE o_custkey = c_custkey AND o_totalprice > c_acctbal * 3)) TO 'exists_non_equi.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT count(*) AS n FROM orders WHERE NOT EXISTS (SELECT * FROM lineitem WHERE l_orderkey = o_orderkey)) TO 'not_exists_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o1.o_orderkey FROM orders o1 WHERE o1.o_totalprice > (SELECT avg(o2.o_totalprice) FROM orders o2 WHERE o2.o_custkey = o1.o_custkey)) TO 'scalar_null_outer_key_avg.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o1.o_orderkey FROM orders o1 WHERE (SELECT count(*) FROM orders o2 WHERE o2.o_custkey = o1.o_custkey) = 0) TO 'scalar_null_outer_key_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT s_suppkey FROM supplier WHERE (SELECT count(*) FROM lineitem WHERE l_suppkey = s_suppkey) > 20) TO 'scalar_null_inner_key.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE (SELECT min(l_quantity) FROM lineitem WHERE l_partkey = p_partkey) < 5 AND (SELECT max(l_quantity) FROM lineitem WHERE l_partkey = p_partkey) > 45) TO 'scalar_two_in_where.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE p_size = 15 OR p_retailprice * 25 > (SELECT avg(l_extendedprice) FROM lineitem WHERE l_partkey = p_partkey)) TO 'scalar_under_or.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE (SELECT count(*) * 2 + 1 FROM lineitem WHERE l_partkey = p_partkey) < 9) TO 'scalar_count_expr.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o_orderkey FROM orders WHERE (SELECT count(l_suppkey) FROM lineitem WHERE l_orderkey = o_orderkey) < (SELECT count(*) FROM lineitem WHERE l_orderkey = o_orderkey)) TO 'scalar_count_column_nulls.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey, (SELECT count(*) FROM lineitem WHERE l_partkey = p_partkey) AS n FROM part) TO 'scalar_select_count.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT o_orderkey, (SELECT max(l_receiptdate) FROM lineitem WHERE l_orderkey = o_orderkey) AS last_receipt FROM orders) TO 'scalar_select_date.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT c.c_custkey FROM customer c, nation n WHERE c.c_nationkey = n.n_nationkey AND c.c_acctbal > (SELECT avg(c2.c_acctbal) FROM customer c2 WHERE c2.c_nationkey = n.n_nationkey)) TO 'scalar_qualified_outer.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT p_partkey FROM part WHERE (SELECT max(l_quantity) FROM lineitem WHERE l_partkey = p_partkey AND l_quantity > 1000) IS NULL) TO 'scalar_empty_body.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT d.p_partkey, d.n FROM (SELECT p_partkey, (SELECT count(*) FROM partsupp WHERE ps_partkey = p_partkey AND ps_availqty > 20) AS n FROM part) d WHERE d.n > 1) TO 'scalar_in_derived.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
COPY (SELECT l_orderkey, l_linenumber FROM lineitem WHERE l_quantity < CAST(l_linenumber AS DOUBLE) * 7.5) TO 'decimal_vs_double.tsv' (FORMAT csv, DELIMITER E'\t', HEADER true);
